/** Composite tab key: sessions are identified by (peerId, sessionId).
 * Sessions on this server (peerId "") use the bare session id.
 *
 * The peer id is escaped: it comes from the connection registry the user
 * edits, so it may contain the separator, and reading an id like `a:b`
 * naively would split it into peer `a` and session `b:<id>` — another
 * peer's session. The other half needs no escaping: session and workspace
 * ids are generated by the server (core/session/repo.ts,
 * core/workspace/repo.ts) and are always UUIDs.
 *
 * The escape touches `%` and the separator only, and is total in both
 * directions, so every id round-trips and no key can fail to parse. */
const SEPARATOR = ":";

export function tabKey(peerId: string, sessionId: string): string {
  return peerId === ""
    ? sessionId
    : `${escapePeerId(peerId)}${SEPARATOR}${sessionId}`;
}

/** Split a tab key back into (peerId, sessionId). */
export function splitTabKey(
  key: string,
): { peerId: string; sessionId: string } {
  const i = key.indexOf(SEPARATOR);
  if (i === -1) return { peerId: "", sessionId: key };
  return {
    peerId: unescapePeerId(key.slice(0, i)),
    sessionId: key.slice(i + 1),
  };
}

/** The tab keys that belong to one peer ("" = this server). Used to re-sync
 * only the sessions of a peer whose event stream just came back, instead of
 * re-reading every open tab. */
export function keysForPeer(
  keys: Iterable<string>,
  peerId: string,
): string[] {
  return [...keys].filter((key) => splitTabKey(key).peerId === peerId);
}

/** The close operations the tab bar offers: the × button and the context
 * menu's plain "close" ("tab"), plus the bulk actions of its submenu. */
export type CloseOperation = "tab" | "toRight" | "toLeft" | "others";

/** The tab ids a close operation targets, in tab order. Pure, so the App
 * can ask the user before running one that would stop a running session —
 * the alternative (each close function checking the views itself) would
 * spread the "which tabs does this operation mean" rule over two modules.
 * A bulk operation whose anchor is no longer open (a stale context menu)
 * targets nothing. */
export function closeTargets(
  op: CloseOperation,
  tabs: readonly string[],
  anchorId: string,
): string[] {
  if (op === "tab") return [anchorId];
  if (op === "others") return tabs.filter((id) => id !== anchorId);
  const index = tabs.indexOf(anchorId);
  if (index === -1) return [];
  return op === "toRight" ? tabs.slice(index + 1) : tabs.slice(0, index);
}

/** `%` → `%25` first, then `:` → `%3A`, so an id that already reads as an
 * escape sequence cannot decode into a separator. */
function escapePeerId(peerId: string): string {
  return peerId.replaceAll("%", "%25").replaceAll(SEPARATOR, "%3A");
}

function unescapePeerId(escaped: string): string {
  return escaped.replaceAll("%3A", SEPARATOR).replaceAll("%25", "%");
}
